      this.log('  gogs-ai chat              - 대화형 모드\n', 'cyan');
      return;
    }

    const cmd = args[0];
    const rest = args.slice(1).join(' ');

    if (cmd === 'ask') {
      await this.ask(rest);
    } else if (cmd === 'audit') {
      await this.audit();
    } else if (cmd === 'route') {
      await this.route(rest);
    } else if (cmd === 'analyze') {
      await this.analyze(rest);
