        }

        // Phase 변경 감지
        const phases = new Set(commits.map(c => c.phase).filter(p => p));
        if (phases.size > 0) {
          console.log(`  📊 Phase: ${Array.from(phases).join(', ')}`);
        }
      } else {
        console.log(`  - 변경사항 없음`);
      }
    } catch (error) {
      console.error(`  ❌ 오류: ${error.message}`);
    }
  }
}

